664     } else if (match(LHS, m_c_Or(m_V, m_Value(Y))) && match(RHS, m_APInt(C))) {
665       // For zero bits in Mask, we can propagate bits from C to V.
666       Known.Zero |= ~*C;
667       if (match(Y, m_APInt(Mask)))
